<?php
require_once __DIR__.'/includes/auth.php';require_role(['Administrator','Asset Manager']);$u=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$asset=get_asset($id,true);if(!$asset||!$asset['deleted_at']||!asset_can_manage($asset,$u)){flash('danger','Asset not found or access denied.');redirect('recycle-bin.php');}$action=(string)($_POST['action']??'');if($action==='restore'){db()->prepare('UPDATE assets SET deleted_at=NULL WHERE id=?')->execute([$id]);audit('asset_restored','Restored asset “'.$asset['title'].'”.');flash('success','Asset restored.');}elseif($action==='purge'){ $paths=db()->prepare('SELECT file_path FROM asset_versions WHERE asset_id=?');$paths->execute([$id]);$files=array_unique(array_merge([$asset['file_path']],array_column($paths->fetchAll(),'file_path')));db()->prepare('DELETE FROM assets WHERE id=?')->execute([$id]);foreach($files as $file)delete_stored_file($file);audit('asset_purged','Permanently deleted asset “'.$asset['title'].'”.');flash('success','Asset and all stored versions were permanently deleted.');}redirect('recycle-bin.php');}
$where=$u['role_name']==='Administrator'?'a.deleted_at IS NOT NULL':'a.deleted_at IS NOT NULL AND a.uploaded_by='.(int)$u['id'];$assets=db()->query("SELECT a.*,u.name uploader_name,c.name category_name FROM assets a JOIN users u ON u.id=a.uploaded_by LEFT JOIN categories c ON c.id=a.category_id WHERE $where ORDER BY a.deleted_at DESC")->fetchAll();$pageTitle='Recycle Bin';$pageSubtitle='Restore deleted assets or permanently remove their files';require __DIR__.'/includes/header.php';?>
<div class="alert alert-warning"><i class="bi bi-exclamation-triangle me-2"></i>Permanent deletion removes every stored version and cannot be undone.</div><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Asset</th><th>Category</th><th>Uploaded by</th><th>Size</th><th>Deleted</th><th></th></tr></thead><tbody><?php foreach($assets as $a):?><tr><td><i class="bi <?=e(asset_icon($a['file_extension']))?> text-primary me-2"></i><strong><?=e($a['title'])?></strong><small class="d-block text-muted ms-4"><?=e($a['original_filename'])?></small></td><td><?=e($a['category_name']??'—')?></td><td><?=e($a['uploader_name'])?></td><td><?=e(human_file_size((int)$a['file_size']))?></td><td><?=e(date('M j, Y g:i A',strtotime($a['deleted_at'])))?></td><td><div class="d-flex gap-2"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="restore"><input type="hidden" name="id" value="<?=$a['id']?>"><button class="btn btn-sm btn-outline-success">Restore</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="purge"><input type="hidden" name="id" value="<?=$a['id']?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Permanently delete this asset and every version? This cannot be undone.">Delete forever</button></form></div></td></tr><?php endforeach;?><?php if(!$assets):?><tr><td colspan="6"><div class="empty-state"><i class="bi bi-trash3"></i><h2 class="h5 mt-3">Recycle Bin is empty</h2></div></td></tr><?php endif;?></tbody></table></div></div>
<?php require __DIR__.'/includes/footer.php';?>

